<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {lookupPlaces} from '@/services/places'
import {inPhilippines} from '@/services/philippines'
import {categories,defaultPreferences,type Place,type Interest,type Preferences} from '@/types/discovery'
import type {ItineraryItem,TripDay} from '@/types'
import {rankPlaces,placeKey,suggestCandidates,visitEstimate,freeWindows,clockLabel,scheduleAdvice,type SuggestedVisit} from '@/composables/discovery'
const props=withDefaults(defineProps<{origin:Place|null;active:boolean;items?:ItineraryItem[];days?:TripDay[];date?:string;timezone?:string;savePlan?:(visits:SuggestedVisit[])=>Promise<void>}>(),{items:()=>[],days:()=>[],date:'',timezone:'Asia/Manila'})
const emit=defineEmits<{highlight:[Place];add:[Place,string];gps:[];origin:[Place];plan:[SuggestedVisit[]]}>()
const preferences=ref<Preferences>(defaultPreferences()),category=ref('all'),radius=ref(5000),limit=ref(6),results=ref<Place[]>([]),state=ref('idle'),failure=ref('')
const compared=ref<string[]>([]),proposal=ref<SuggestedVisit[]|null>(null),saving=ref(false),planMessage=ref(''),originId=ref('')
const interests:Interest[]=['food','nature','beaches','culture','adventure','shopping']
let request:AbortController|undefined,version=0,timer:ReturnType<typeof setTimeout>
const starts=computed(()=>props.items.filter(i=>i.latitude!=null&&i.longitude!=null&&inPhilippines(i.latitude,i.longitude)))
const start=computed<Place|null>(()=>{const i=starts.value.find(i=>i.id===originId.value);return i?{name:i.title,latitude:i.latitude!,longitude:i.longitude!}:props.origin})
const ranked=computed(()=>start.value?rankPlaces(results.value,start.value,preferences.value,props.items,props.days):[])
const comparisons=computed(()=>ranked.value.filter(r=>compared.value.includes(placeKey(r.place))))
const windows=computed(()=>freeWindows(preferences.value,props.items,props.days))
watch(()=>props.date,d=>{preferences.value.date=d},{immediate:true})
async function load(){
 request?.abort();const token=++version;results.value=[];failure.value='';limit.value=6;compared.value=[]
 if(!props.active||!start.value){state.value='idle';return}
 const controller=request=new AbortController(),point={...start.value};state.value='loading'
 try{const rows=await lookupPlaces({mode:'nearby',lat:String(point.latitude),lon:String(point.longitude),category:category.value,radius:String(radius.value)},controller.signal)
  if(token!==version)return
  results.value=rows.filter(p=>inPhilippines(p.latitude,p.longitude,p.countryCode));state.value=results.value.length?'ready':'empty'
 }catch{if(token===version){state.value='error';failure.value='Nearby places couldn’t load. Retry, or continue with your selected location.'}}
}
watch(()=>[props.active,start.value?.latitude,start.value?.longitude,category.value,radius.value],()=>{request?.abort();version++;clearTimeout(timer);if(!props.active)return;results.value=[];state.value=start.value?'loading':'idle';timer=setTimeout(load,350)},{immediate:true})
onBeforeUnmount(()=>{clearTimeout(timer);version++;request?.abort()})
function compare(p:Place){const k=placeKey(p);if(compared.value.includes(k))compared.value=compared.value.filter(x=>x!==k);else if(compared.value.length<3)compared.value.push(k)}
function suggest(){proposal.value=suggestCandidates(ranked.value,preferences.value,props.items,props.days);planMessage.value=''}
function replace(visit:SuggestedVisit,key:string){const p=results.value.find(p=>placeKey(p)===key);if(p){visit.place=p;visit.estimate=visitEstimate(p)}}
async function save(){if(saving.value||!proposal.value)return;const chosen=proposal.value.filter(p=>p.selected);if(!chosen.length)return
 if(!props.savePlan){emit('plan',chosen);return}
 saving.value=true;planMessage.value=''
 try{await props.savePlan(chosen);proposal.value=null;planMessage.value='Selected stops saved.'}catch{planMessage.value='Some stops could not be saved. Your selections are kept. Retry safely.'}finally{saving.value=false}
}
const advice=(v:SuggestedVisit)=>scheduleAdvice({scheduled_time:v.start,end_time:v.end,end_day_offset:v.nextDay?1:0},v.date,props.items,props.days,preferences.value.style,v.place)
</script>
<template><section class="nearby" aria-label="Nearby discovery">
 <header><p class="eyebrow">A little local inspiration</p><h3>Places to explore near {{start?.name||'your selected place'}}</h3><p class="fine">Real places from Geoapify / OpenStreetMap. Distances are approximate, in a straight line.</p></header>
 <details class="preferences"><summary>Help me choose <span>Optional</span></summary><div class="preference-body">
  <fieldset><legend>Your interests</legend><div class="interest-list"><label v-for="i in interests" :key="i"><input v-model="preferences.interests" type="checkbox" :value="i" />{{i}}</label></div></fieldset>
  <label>Starting location<select v-model="originId"><option value="">Selected map pin</option><option v-for="s in starts" :key="s.id" :value="s.id">{{s.title}}</option></select></label><button type="button" @click="emit('gps')">Use my current location</button>
  <label>Visit date<input v-model="preferences.date" type="date" /></label><div class="pair"><label>Available from<input v-model="preferences.start" type="time" /></label><label>Until<input v-model="preferences.end" type="time" /></label></div><label class="check"><input v-model="preferences.nextDay" type="checkbox" />Window ends next day</label>
  <p class="fine">Times use {{timezone}}. No timezone is changed by selecting a place.</p>
  <div class="pair"><label>Preferred distance<select v-model.number="preferences.distanceKm"><option :value="2">Within 2 km</option><option :value="5">Within 5 km</option><option :value="10">Within 10 km</option><option :value="30">Within 30 km</option></select></label><label>Budget<select v-model="preferences.budget"><option value="any">No preference</option><option value="low">Budget</option><option value="medium">Moderate</option><option value="high">Higher budget</option></select></label></div>
  <label>Travel style<select v-model="preferences.style"><option value="relaxed">Relaxed</option><option value="balanced">Balanced</option><option value="packed">Packed</option></select></label><label class="check"><input v-model="preferences.accessibility" type="checkbox" />Check wheelchair access</label><p class="fine">Access needs vary. Missing information is not confirmation of suitability.</p>
  <p v-for="w in windows.slice(0,3)" :key="w.start" class="fine">Free window {{clockLabel(w.start)}}–{{clockLabel(w.end)}} · excludes travel.</p>
  <details><summary>How suggestions are ranked</summary><p class="fine">Interest matches come first, then preferred distance, available visit time and known information. We favour category variety and flag existing visits. This is preference fit, not a guarantee. Price, hours and accessibility stay unknown unless supplied. Route feasibility is not verified.</p></details>
 </div></details>
 <nav class="filters" aria-label="Place categories"><button v-for="c in [{id:'all',label:'All places'},...categories]" :key="c.id" type="button" :aria-pressed="category===c.id" @click="category=c.id">{{c.label}}</button></nav>
 <p v-if="state==='idle'" class="fine">Select a Philippine destination to find places nearby.</p><p v-if="state==='loading'" role="status">Finding nearby places…</p>
 <p v-if="state==='empty'" role="status">No places found in this area. Try another category or expand the search.</p>
 <p v-if="state==='error'" role="status">{{failure}} <button type="button" @click="load">Retry nearby places</button></p>
 <div class="discovery-cards"><article v-for="r in ranked.slice(0,limit)" :key="placeKey(r.place)" class="discovery-card">
  <div class="category-art" aria-hidden="true">{{categories.find(c=>c.id===r.place.category)?.symbol||'✧'}}<span>PHILIPPINES</span></div>
  <div class="card-copy"><p class="fine category">{{categories.find(c=>c.id===r.place.category)?.label||'Place'}} · {{r.match}}</p><h4>{{r.place.name}}</h4><p class="fine">{{r.place.address||'Address unavailable'}}</p><ul class="reasons"><li v-for="reason in r.reasons" :key="reason">{{reason}}</li></ul><p class="fine">{{r.estimate.minutes}} min · {{r.estimate.source}}</p><p class="fine">{{r.unknown[0]}}</p>
   <div class="card-actions"><button type="button" @click="emit('highlight',r.place)">View on map</button><button type="button" class="primary" @click="emit('add',r.place,preferences.date)">{{r.planned?'Add repeat visit':'Add to itinerary'}}</button><button type="button" :aria-pressed="compared.includes(placeKey(r.place))" :disabled="compared.length>=3&&!compared.includes(placeKey(r.place))" @click="compare(r.place)">Compare</button></div>
  </div></article></div>
 <div class="card-actions"><button v-if="ranked.length>limit" type="button" @click="limit+=6">Show more</button><button v-if="start&&radius<30000" type="button" @click="radius=radius===5000?15000:30000">Expand to {{radius===5000?15:30}} km</button><button v-if="ranked.length" type="button" @click="suggest">Suggest a day plan</button></div>
 <section v-if="comparisons.length" class="comparison" aria-label="Compare places"><h3>Compare {{comparisons.length}} places</h3><div class="compare-grid"><article v-for="r in comparisons" :key="placeKey(r.place)"><h4>{{r.place.name}}</h4><p>{{r.place.category}} · {{r.place.address||'Address unavailable'}}</p><p>{{r.distance.toFixed(1)}} km straight-line · travel time unknown</p><p>{{r.estimate.minutes}} minutes · {{r.estimate.source}}</p><p>{{r.place.price?.text||'Price unavailable'}}</p><p>{{r.place.openingHours||'Opening hours unavailable'}} · {{preferences.date||'date undecided'}}; check before visiting.</p><p>Wheelchair access: {{r.place.accessibility||'unknown'}}</p><p v-for="reason in r.reasons" :key="reason">{{reason}}</p><button type="button" @click="compare(r.place)">Remove from comparison</button></article></div></section>
 <section v-if="proposal" class="proposal" aria-label="Review suggested places"><h3>A few possibilities for your day</h3><p class="fine">These are candidates, not a verified route. Times are left flexible because road, ferry and flight connections are unknown. Existing stops stay unchanged. Visit durations are estimates; no travel buffers have been invented.</p><p v-if="!proposal.length">No additional visits fit this time window and pace. Adjust your preferences or browse places individually.</p>
  <article v-for="v in proposal" :key="v.id"><label class="check"><input v-model="v.selected" type="checkbox" :disabled="saving" />Include {{v.place.name}}</label><label>Place<select :value="placeKey(v.place)" :disabled="saving" @change="replace(v,($event.target as HTMLSelectElement).value)"><option v-for="p in results" :key="placeKey(p)" :value="placeKey(p)">{{p.name}}</option></select></label><p class="fine">{{v.estimate.minutes}} minutes · {{v.estimate.source}}</p><label>Date<input v-model="v.date" type="date" :disabled="saving" /></label><div class="pair"><label>Start time<input v-model="v.start" type="time" :disabled="saving" /></label><label>End time<input v-model="v.end" type="time" :disabled="saving" /></label></div><label class="check"><input v-model="v.nextDay" type="checkbox" :disabled="saving" />Ends next day</label><label>Notes<input v-model="v.notes" :disabled="saving" /></label><p v-for="a in advice(v)" :key="a" class="fine">{{a}}</p><button type="button" :disabled="saving" @click="proposal=proposal.filter(p=>p.id!==v.id)">Remove suggestion</button></article>
  <div class="card-actions"><button type="button" :disabled="saving" @click="proposal=null">Cancel proposal</button><button type="button" class="primary" :disabled="saving||!proposal.some(p=>p.selected)" @click="save">{{saving?'Saving…':'Add selected stops'}}</button></div>
 </section><p v-if="planMessage" role="status">{{planMessage}}</p>
</section></template>
<style scoped>
.nearby{min-width:0}.nearby h3{font:25px/1.2 Georgia,serif;margin:7px 0 12px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.14em;color:#667557}.fine{font-size:13px;line-height:1.55;color:#665e51;overflow-wrap:anywhere}.preferences{background:#eeeee2;border-radius:12px;padding:0 12px;margin:16px 0}.preferences summary{min-height:44px;padding:12px 0;cursor:pointer}.preferences summary span{font-size:12px;color:#626f55;margin-left:8px}.preference-body{display:grid;gap:12px;padding-bottom:14px}.interest-list,.filters,.card-actions{display:flex;flex-wrap:wrap;gap:6px}.interest-list label{display:flex;align-items:center;gap:6px;min-height:44px;text-transform:capitalize}.check{display:flex;align-items:center;gap:8px;min-height:44px}input[type=checkbox]{width:20px;height:20px;min-height:20px;accent-color:#74283c}.filters{margin:12px 0}.filters button{font-size:13px}.filters button[aria-pressed=true]{background:#74283c;color:#fffaf0}.discovery-cards{display:grid;gap:14px}.discovery-card{border:1px solid #ded5c3;border-radius:12px;overflow:hidden;background:#fffaf0}.category-art{background:#e4e9da;color:#657557;height:66px;padding:12px 18px;font:32px Georgia,serif;display:flex;justify-content:space-between;align-items:center}.category-art span{font:9px sans-serif;letter-spacing:.16em}.card-copy{padding:14px}.card-copy h4,.comparison h4{font:24px/1.2 Georgia,serif;margin:7px 0}.category{margin-top:0}.reasons{font-size:13px;line-height:1.55;padding-left:18px}.card-actions{margin-top:12px}.card-actions button{font-size:13px}.comparison,.proposal{margin-top:24px;padding:14px;background:#eeeee2;border-radius:12px}.compare-grid{display:grid;gap:12px}.compare-grid article,.proposal article{padding:14px;background:#fffaf0;border-radius:10px;margin-bottom:12px;font-size:13px;line-height:1.5;overflow-wrap:anywhere}.proposal article{display:grid;gap:10px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair>*{min-width:0}label{display:block;font-size:13px}input,select{display:block;width:100%;min-width:0;box-sizing:border-box;font:16px inherit;font-size:16px;min-height:44px;padding:8px;border:1px solid #cfc5b3;border-radius:8px;background:#fffdf7;color:#51493f}fieldset{border:0;padding:0}legend{font-size:13px}button{min-height:44px;min-width:44px;font-size:16px;padding:8px 12px;border:1px solid #cfc5b3;border-radius:9px;background:#faf6ed;color:#74283c;cursor:pointer}button.primary{background:#74283c;color:#fffaf0}button:disabled{opacity:.5;cursor:default}:is(button,input,select,summary):focus-visible{outline:2px solid #74283c;outline-offset:3px}
</style>
